export function getSettingsHelpKey(path: string): string {
  for (const [pattern, key] of SETTINGS_PATH_TO_HELP_KEY) {
    if (pattern.test(path)) {
      return key;
    }
  }
  return 'settings';
}

export function getLink(name: string) {
  const lang_code = LocalStorage.getItem(CONSTANTS.selected_language) as string;
  let link_name = name;
  if (!link_name) {
    return baseUrl;
  }
  try {
    if (lang_code == 'de') {
      link_name = link_name + '_de';
    } else if (lang_code == 'es-es') {
      link_name = link_name + '_es';
    } else if (lang_code == 'fr') {
      link_name = link_name + '_fr';
    } else if (lang_code == 'nl') {
      link_name = link_name + '_nl';
    } else if (lang_code == 'it') {
      link_name = link_name + '_it';
    } else if (lang_code == 'zh') {
      link_name = link_name + '_zh';
    } else {
      link_name = link_name + '_en';
    }
     
    return eval(link_name);
  } catch (error) {
     
    return eval('dashboard');
  }
}
